	if err != nil {
		return nil, err
	}
	albumIDs := make([]string, 0, len(als))
	for _, al := range als {
		albumIDs = append(albumIDs, al.ID)
	}
	mfs, err := artwork.ds.MediaFile(ctx).GetAll(model.QueryOptions{Filters: squirrel.Eq{"album_id": albumIDs}})
